+  ss << "  return;\n";
+  ss << "}\n";
+}
+
+void TilingLib::GenCallCubeTilingCacheWrite(std::stringstream &ss,
+                                            const std::vector<std::string> &dynamic_shape_vars) const {
+  ss << "g_cube_tiling_cache_valid = true;\n";
+  for (const auto &var_name : dynamic_shape_vars) {
