    try:
        wrapper_obj = compile_host_obj_file(args, temp_dir, source_file)
        link_shared(
            tmp_so_path,
            [wrapper_obj],
            link_libraries=CV_HOST_LINK_LIBRARIES,
            extra_link_options=get_shared_cv_wrapper_soname_options(so_path),
