        return so_path
    os.makedirs(os.path.dirname(so_path), exist_ok=True)
    lock_path = f"{so_path}.lock"
    with open(lock_path, "w") as lock_file:
        fcntl.flock(lock_file, fcntl.LOCK_EX)
        try:
            if os.path.exists(so_path):
                return so_path
