468	    const ascir::FusedScheduledResult &fused_schedule_result) const {
469	  ascir::FusedScheduledResult elemwise_schedule_result = fused_schedule_result;
470	  const bool is_cube_fused_scheduled = ascgen_utils::IsCubeFusedScheduled(fused_schedule_result);
471	  if (enable_autofuse_pgo_ && !IsSupportedInductorPgoScene(fused_schedule_result)) {
472	    GELOGE(af::FAILED, "Inductor MSPTI PGO only supports static, non-CV kernels");
473	    return {{kTilingDefAndConstIdentify, ascgen_utils::INVALID_TILING}};
474	  }
475	  if (is_cube_fused_scheduled) {
476	    GE_ASSERT_SUCCESS(ascgen_utils::ProcessCubeFusionResultDynamic(elemwise_schedule_result));
477	  }
478	  std::map<std::string, std::string> tiling_file_name_to_content =
479	      GetTilingHeaders(elemwise_schedule_result, true, is_cube_fused_scheduled);
480	  GE_CHK_BOOL_RET_STATUS_NOLOG(CheckTilingHeadersValid(tiling_file_name_to_content), tiling_file_name_to_content);
481	  std::stringstream ss;
482	
483	  ss << "#pragma GCC diagnostic push\n" << "#pragma GCC diagnostic ignored \"-Wreturn-type-c-linkage\"\n";
484	  ss << "extern \"C\" std::string GetTilingDataRepr(const AutofuseTilingData *tiling_data);\n";
485	  ss << "#pragma GCC diagnostic pop\n";
486	  ss << TilingFuncDefForInductor(fused_schedule_result, elemwise_schedule_result) << std::endl;
487	  if (!is_cube_fused_scheduled) {
488	    GenInductorTopnSources(elemwise_schedule_result, ss, tiling_file_name_to_content);
489	  }
490	  // 生成GenConstTilingData方法（对所有场景生成，包括CV fusion静态shape）
491	  ss << TilingData("Autofuse").GenerateConst(fused_schedule_result) << std::endl;
492	  if (is_cube_fused_scheduled) {
493	    tiling_file_name_to_content[kCubeKernelTilingWrapperHpp] = kCubeKernelTilingWrapperHppValue;
494	    tiling_file_name_to_content[kCubeKernelTilingWrapperCpp] = kCubeKernelTilingWrapperInclude;
495	    tiling_file_name_to_content[kCubeKernelTilingWrapperCpp] += kCubeKernelTilingWrapperCppValue;
496	  }
497	  const std::string entry_body = tiling_file_name_to_content[kTilingDefAndConstIdentify] + ss.str();
498	  const auto entry_options =
499	      GetInductorEntryTranslationUnitOptions(elemwise_schedule_result, is_cube_fused_scheduled, enable_autofuse_pgo_);
500	  tiling_file_name_to_content[kTilingDefAndConstIdentify] = RenderEntryTranslationUnit(entry_body, entry_options);
501	
502	  return tiling_file_name_to_content;
503	}
