509	void TilingLib::GenPgoMixTilingTable(const ascir::FusedScheduledResult &fused_schedule_result,
510	                                     std::stringstream &ss) const {
511	  for (size_t graph_id = 0U; graph_id < fused_schedule_result.node_idx_to_scheduled_results.size(); graph_id++) {
512	    const auto &scheduled_results = fused_schedule_result.node_idx_to_scheduled_results[graph_id];
513	    ss << "std::vector<uint32_t> g_mix_graph" << graph_id << "_tiling_keys = {" << std::endl;
514	    for (size_t result_id = 0U; result_id < scheduled_results.size(); result_id++) {
515	      const auto &schedule_groups = scheduled_results[result_id].schedule_groups;
516	      bool has_workspace_node = false;
517	      for (size_t group_id = 0U; group_id < schedule_groups.size() - 1U; group_id++) {
518	        const auto &impl_graphs = schedule_groups[group_id].impl_graphs;
519	        has_workspace_node = std::any_of(impl_graphs.begin(), impl_graphs.end(),
520	                                         [](const auto &graph) { return HasWorkSpaceNode(graph); });
521	      }
522	      if (has_workspace_node) {
523	        ss << "    " << result_id << "," << std::endl;
524	      }
525	    }
526	    ss << "};" << std::endl;
527	  }
